//! The signed fixed-point types `Q8_8` (i16 storage) and `Q16_16` (i32 storage).
//!
//! Both are generated by one macro, so they share every rule. This file holds the types, their
//! constants and constructors; `arith.rs` holds their arithmetic. There is no conversion from or to
//! a float, and no conversion between the two types except the named `widen` and
//! `narrow_saturating`. The ordering of a value is the ordering of its bits (derived `Ord`), so a
//! threshold comparison is an integer comparison.
//!
//! REF: `CODEX/05_PROJECT/SPR-010_FixedPoint.md` T-01; `05.5` §2.1; `05.1` §6 item 4.

use super::round::{div_round_half_even, saturate_i16, saturate_i32, shr_round_half_even};

macro_rules! fixed_point_type {
    (
        $(#[$meta:meta])*
        $name:ident, storage = $bits:ty, int = $int:ty, frac_bits = $frac:expr,
        saturate = $saturate:ident
    ) => {
        $(#[$meta])*
        #[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
        pub struct $name($bits);

        impl $name {
            /// The number of fractional bits: a value is `bits / 2^FRAC_BITS`.
            pub const FRAC_BITS: u32 = $frac;
            /// Zero.
            pub const ZERO: Self = Self(0);
            /// One.
            pub const ONE: Self = Self(1 << $frac);
            /// The smallest positive value, `2^-FRAC_BITS`: one step of the type.
            pub const EPSILON: Self = Self(1);
            /// The most negative value; every result below it saturates to it.
            pub const MIN: Self = Self(<$bits>::MIN);
            /// The most positive value; every result above it saturates to it.
            pub const MAX: Self = Self(<$bits>::MAX);

            /// Builds a value from its raw bits (`bits / 2^FRAC_BITS`); for storage and hashing.
            #[must_use]
            pub const fn from_bits(bits: $bits) -> Self {
                Self(bits)
            }

            /// Returns the raw bits (`self * 2^FRAC_BITS`); for storage and hashing.
            #[must_use]
            pub const fn to_bits(self) -> $bits {
                self.0
            }

            /// Builds the value of an integer. Total: the integer type is exactly the type's range.
            #[must_use]
            pub const fn from_int(n: $int) -> Self {
                Self((n as $bits) << $frac)
            }

            /// Builds the value nearest `numerator / denominator`, rounding half to even.
            ///
            /// Returns `None` if `denominator` is zero or the rounded value is out of range: a
            /// constant that does not fit is a data error, never silently saturated.
            #[must_use]
            pub const fn from_ratio(numerator: i64, denominator: i64) -> Option<Self> {
                let scaled = (numerator as i128) << $frac;
                match div_round_half_even(scaled, denominator as i128) {
                    Some(bits) if bits >= <$bits>::MIN as i128 && bits <= <$bits>::MAX as i128 => {
                        Some(Self($saturate(bits)))
                    }
                    _ => None,
                }
            }
        }
    };
}

fixed_point_type! {
    /// A signed Q8.8 fixed-point number: `i16` bits, value `bits / 256`, range
    /// `[-128, 128 - 1/256]`. The column type `q8_8` of the system specs (psychology scores).
    ///
    /// There is deliberately no `Div` operator (use `checked_div`) and no conversion from or to a
    /// float (`05.1` §6 item 4).
    Q8_8, storage = i16, int = i8, frac_bits = 8, saturate = saturate_i16
}

fixed_point_type! {
    /// A signed Q16.16 fixed-point number: `i32` bits, value `bits / 65536`, range
    /// `[-32768, 32768 - 1/65536]`. The column type `q16_16` of the system specs (rates,
    /// probabilities, thresholds).
    ///
    /// There is deliberately no `Div` operator (use `checked_div`) and no conversion from or to a
    /// float (`05.1` §6 item 4).
    Q16_16, storage = i32, int = i16, frac_bits = 16, saturate = saturate_i32
}

impl Q8_8 {
    /// Converts to `Q16_16` exactly: every `Q8_8` value is a `Q16_16` value.
    #[must_use]
    pub const fn widen(self) -> Q16_16 {
        Q16_16::from_bits((self.0 as i32) << 8)
    }
}

impl Q16_16 {
    /// Converts to `Q8_8`, rounding half to even to 8 fractional bits, then saturating.
    #[must_use]
    pub const fn narrow_saturating(self) -> Q8_8 {
        Q8_8::from_bits(saturate_i16(shr_round_half_even(self.0 as i128, 8)))
    }
}

#[cfg(test)]
mod tests {
    use super::{Q8_8, Q16_16};

    #[test]
    fn constants_have_the_documented_bits() {
        assert_eq!(Q8_8::ONE.to_bits(), 256);
        assert_eq!(Q16_16::ONE.to_bits(), 65_536);
        assert_eq!(Q16_16::EPSILON.to_bits(), 1);
        assert_eq!(Q8_8::from_int(i8::MIN), Q8_8::MIN);
        assert_eq!(Q8_8::from_int(i8::MAX).to_bits(), 127 * 256);
        assert_eq!(Q16_16::from_int(-3).to_bits(), -3 * 65_536);
        assert_eq!(Q16_16::default(), Q16_16::ZERO);
    }

    #[test]
    fn from_ratio_rounds_half_to_even() {
        assert_eq!(Q8_8::from_ratio(1, 3), Some(Q8_8::from_bits(85))); // 85.33 -> 85
        assert_eq!(Q8_8::from_ratio(1, 512), Some(Q8_8::ZERO)); // 0.5 step -> 0 (even)
        assert_eq!(Q8_8::from_ratio(3, 512), Some(Q8_8::from_bits(2))); // 1.5 steps -> 2 (even)
        assert_eq!(Q8_8::from_ratio(-3, 512), Some(Q8_8::from_bits(-2)));
        assert_eq!(Q16_16::from_ratio(-1, -2), Some(Q16_16::from_bits(32_768)));
    }

    #[test]
    fn from_ratio_refuses_zero_denominators_and_out_of_range_values() {
        assert_eq!(Q16_16::from_ratio(1, 0), None);
        assert_eq!(Q16_16::from_ratio(32_768, 1), None);
        assert_eq!(Q16_16::from_ratio(-32_768, 1), Some(Q16_16::MIN));
        assert_eq!(Q16_16::from_ratio(i64::MAX, 1), None);
        assert_eq!(Q8_8::from_ratio(i64::MIN, -1), None);
    }

    #[test]
    fn ordering_is_the_ordering_of_values() {
        let ascending = [
            Q16_16::MIN,
            Q16_16::from_int(-1),
            Q16_16::ZERO,
            Q16_16::EPSILON,
            Q16_16::ONE,
            Q16_16::MAX,
        ];
        assert!(ascending.windows(2).all(|pair| pair[0] < pair[1]));
        assert!(Q8_8::from_bits(-1) < Q8_8::ZERO);
    }

    #[test]
    fn widen_and_narrow_round_trip() {
        for bits in [i16::MIN, -257, -1, 0, 1, 255, i16::MAX] {
            let q = Q8_8::from_bits(bits);
            assert_eq!(q.widen().narrow_saturating(), q);
        }
        assert_eq!(Q16_16::from_int(200).narrow_saturating(), Q8_8::MAX);
        assert_eq!(Q16_16::from_int(-200).narrow_saturating(), Q8_8::MIN);
        assert_eq!(Q16_16::from_bits(128).narrow_saturating(), Q8_8::ZERO); // half a Q8_8 step: even
        assert_eq!(
            Q16_16::from_bits(384).narrow_saturating(),
            Q8_8::from_bits(2)
        );
    }
}
